@Override public int addTrack(Format format){
  try {
    String sampleMimeType=checkNotNull(format.sampleMimeType);
    MediaFormat mediaFormat;
    if (MimeTypes.isAudio(sampleMimeType)) {
      mediaFormat=MediaFormat.createAudioFormat(castNonNull(sampleMimeType),format.sampleRate,format.channelCount);
    }
    else {
      mediaFormat=MediaFormat.createVideoFormat(castNonNull(sampleMimeType),format.width,format.height);
      mediaMuxer.setOrientationHint(format.rotationDegrees);
    }
    MediaFormatUtil.setCsdBuffers(mediaFormat,format.initializationData);
    return mediaMuxer.addTrack(mediaFormat);
  } catch (NullPointerException e) {
    throw new IllegalArgumentException("Format or its fields cannot be null", e);
  } catch (IllegalArgumentException e) {
    throw new IllegalArgumentException("Invalid format parameters", e);
  }
}
